// PostToolUse: log tool call and estimate token cost
const fs = require('fs');

const ESTIMATES = {
  Read: 800, Write: 600, Edit: 400, Bash: 300,
  Glob: 100, Grep: 200, Agent: 8000, WebFetch: 1500,
  WebSearch: 1000, default: 400
